function reloadCaptcha(imgCaptcha) {
    const base = getVikonCoreScriptUrl();
    imgCaptcha.src = `${base}scripts/captcha.php?sid=${Math.random()}`;
}

function initHotLineIfNeed(container) {
    const btnFeedbackSend = container.querySelector('button[type="submit"]');
    if (btnFeedbackSend) {
        const imgCaptcha = container.querySelector('img[alt="captcha"]');
        const nameField = container.querySelector('[name="name"]');
        const emailField = container.querySelector('[name="email"]');
        const messageField = container.querySelector('[name="message"]');
        const policyField = container.querySelector('[name="consent"]');
        const captchaField = container.querySelector('[name="captcha"]');

        let subjectField = container.querySelector('[name="subject"]');
        if (!subjectField) {
            subjectField = document.createElement('input');
            subjectField.type = 'hidden';
            subjectField.name = 'subject';
            subjectField.value = 'Обращение с сайта';

            let form = container.querySelector('form');
            if (!form) {
                // Если формы нет, обернем содержимое в форму
                form = document.createElement('form');
                form.className = 'feedback-form';
                Array.from(container.children).forEach(child => {
                    form.appendChild(child);
                });
                container.appendChild(form);
            }
            form.appendChild(subjectField);
        }

        // Инициализация CAPTCHA
        if (imgCaptcha) {
            reloadCaptcha(imgCaptcha);
            imgCaptcha.addEventListener('click', () => {
                reloadCaptcha(imgCaptcha);
            });
        }

        btnFeedbackSend.addEventListener('click', (e) => {
            e.preventDefault();

            let feedbackStatus = container.querySelector('.feedback-status');
            if (!feedbackStatus) {
                const textRight = container.querySelector('.text-right');
                if (textRight) {
                    feedbackStatus = document.createElement('div');
                    feedbackStatus.className = 'feedback-status mb-3';
                    textRight.parentNode.insertBefore(feedbackStatus, textRight);
                }
            }

            [nameField, emailField, messageField, policyField, captchaField].forEach(field => {
                if (field && field.parentElement) {
                    field.parentElement.classList.remove('has-error');
                }
            });

            let hasErrors = false;
            const errorMessages = [];

            if (!nameField || !nameField.value.trim()) {
                nameField.parentElement.classList.add('has-error');
                errorMessages.push('Укажите ваше имя');
                hasErrors = true;
            }

            if (!emailField || !emailField.value.trim() || !isValidEmail(emailField.value)) {
                emailField.parentElement.classList.add('has-error');
                errorMessages.push('Укажите корректный email');
                hasErrors = true;
            }

            if (!messageField || !messageField.value.trim()) {
                messageField.parentElement.classList.add('has-error');
                errorMessages.push('Введите текст сообщения');
                hasErrors = true;
            }

            if (!policyField || !policyField.checked) {
                policyField.parentElement.classList.add('has-error');
                errorMessages.push('Необходимо принять условия соглашения');
                hasErrors = true;
            }

            if (!captchaField || !captchaField.value.trim()) {
                captchaField.parentElement.classList.add('has-error');
                errorMessages.push('Введите код с картинки');
                hasErrors = true;
            }

            if (hasErrors) {
                showFeedbackStatus(feedbackStatus, errorMessages, 'danger');
                return;
            }

            const formData = new FormData();
            formData.append('name', nameField.value);
            formData.append('email', emailField.value);
            formData.append('message', messageField.value);
            formData.append('consent', policyField.checked ? '1' : '0');
            formData.append('captcha', captchaField.value);
            formData.append('subject', subjectField.value);

            const feedbackUrl = `${getVikonCoreScriptUrl()}scripts/vsoko_feedback.php`;

            fetch(feedbackUrl, {
                method: 'POST',
                body: formData
            })
                .then(response => response.json())
                .then(res => {
                    if (res.success) {
                        showFeedbackStatus(feedbackStatus, 'Сообщение отправлено', 'success');

                        // Очистка формы
                        nameField.value = '';
                        emailField.value = '';
                        messageField.value = '';
                        policyField.checked = false;
                        captchaField.value = '';

                        if (imgCaptcha) {
                            reloadCaptcha(imgCaptcha);
                        }
                    } else {
                        const messages = res.messages || [res.message || 'Ошибка при отправке'];
                        if (res.errorID) {
                            res.errorID.forEach(item => {
                                const errorField = container.querySelector(`[name="${item}"]`);
                                if (errorField && errorField.parentElement) {
                                    errorField.parentElement.classList.add('has-error');
                                }
                            });
                        }
                        showFeedbackStatus(feedbackStatus, messages, 'danger');
                        if (imgCaptcha) {
                            reloadCaptcha(imgCaptcha);
                            captchaField.value = '';
                        }
                    }
                })
                .catch(error => {
                    console.error('Error:', error);
                    showFeedbackStatus(feedbackStatus, ['Ошибка сети. Попробуйте позже.'], 'danger');
                });
        });
    }
}

function showFeedbackStatus(element, messages, type) {
    if (!element) return;

    const isSuccess = type === 'success';
    const bgClass = isSuccess ? 'alert-success' : 'alert-danger';

    element.className = `feedback-status alert ${bgClass} mb-3`;
    element.style.display = 'block';
    element.textContent = '';

    if (Array.isArray(messages)) {
        if (messages.length === 1) {
            const textElement = document.createTextNode(messages[0]);
            element.appendChild(textElement);
        } else {
            // Несколько сообщений - создаем список
            const ul = document.createElement('ul');
            ul.className = 'mb-0 mt-1';
            ul.style.paddingLeft = '1.5rem';

            messages.forEach(message => {
                const li = document.createElement('li');
                li.textContent = message;
                ul.appendChild(li);
            });

            element.appendChild(ul);
        }
    } else {
        const textElement = document.createTextNode(messages);
        element.appendChild(textElement);
    }
}

function isValidEmail(email) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
}

function getVikonCoreScriptUrl() {
    const meta = document.querySelector('meta[name="vikon_core_path"]');
    const corePath = meta ? meta.getAttribute('content') : null;

    if (!corePath) {
        return '/vikon_core/';
    }

    return corePath.endsWith('/') ? corePath : corePath + '/';
}

document.addEventListener('DOMContentLoaded', () => {
    const container = document.querySelector('[data-feedback-form]');
    if (container) {
        initHotLineIfNeed(container);
    }
});
